$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$r=Get-Content -LiteralPath(Join-Path $PSScriptRoot 'run-kubernetes-bootstrap-state-consistency-diagnostic.ps1')-Raw
foreach($x in @("ConfirmImpact='Low'","DiagnosticId='ob-k8s-bootstrap-state-consistency-003'",'explicit_bootstrap_state_consistency_approval_required','Resolve-DockerInspectState','Complete-RedirectedProcess','Assert-BootstrapStateCapture','first-inspect-candidate-capture.json','inspect-shape-error.json',"State `$docker 'first-live'","State `$docker 'final-live'",'bootstrap-kubelet.conf','kubelet.conf','kube-apiserver.yaml','kubeadm.yaml.new','cri-version-capture.json','cri-containers-capture.json','profile_deleted=$false','application_manifest_applied=$false','workload_started=$false','toxic_created=$false','scientific_fault_started=$false','minikube stop')){if(-not$r.Contains($x)){throw "state_consistency_runner_contract_missing:$x"}}
foreach($x in @('minikube delete','apply -k','config\online-boutique','manage-network-delay-proxy','toxic add')){if($r.Contains($x)){throw "state_consistency_forbidden_scope:$x"}}
$v=Get-Content -LiteralPath(Join-Path $PSScriptRoot 'verify-kubernetes-bootstrap-state-consistency-diagnostic.ps1')-Raw;foreach($x in @('P2-KUBERNETES-BOOTSTRAP-STATE-CONSISTENCY-DIAG-001','Read-EvidenceJson','start_exit_code_or_observations_missing','state_capture_failed','state_path_missing','cri_container_list_invalid','host_health_gate_failed')){if(-not$v.Contains($x)){throw "state_consistency_verifier_contract_missing:$x"}}
Write-Output 'kubernetes_bootstrap_state_consistency_contract_tests=passed'
